  const [selectedTask, setSelectedTask] = useState('t1');
  const [ideOpenWindows, setIdeOpenWindows] = useState(['chat-history', 'commit']);
  const [plainFileGutterCommentsEnabled, setPlainFileGutterCommentsEnabled] = useState(false);
